// Normaliza o email recebido (formatos variam) e monta SQL + aviso pro Thiago.
const j = items[0].json || {};
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");

function extrairDe() {
  const f = j.from;
  if (!f) return { email: 'desconhecido', nome: '' };
  if (typeof f === 'string') {
    const m = f.match(/^\s*"?([^"<]*)"?\s*<([^>]+)>/);
    return m ? { nome: m[1].trim(), email: m[2].trim() } : { nome: '', email: f.trim() };
  }
  if (f.value && f.value[0]) return { nome: f.value[0].name || '', email: f.value[0].address || 'desconhecido' };
  if (f.text) return extrairDeStr(f.text);
  return { email: String(f).substring(0, 100), nome: '' };
}
function extrairDeStr(s) {
  const m = String(s).match(/^\s*"?([^"<]*)"?\s*<([^>]+)>/);
  return m ? { nome: m[1].trim(), email: m[2].trim() } : { nome: '', email: String(s).trim() };
}
const de = extrairDe();
const assunto = String(j.subject || '(sem assunto)').substring(0, 300);
let corpo = String(j.textPlain || j.text || '').trim();
if (!corpo && j.textHtml) corpo = String(j.textHtml).replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
corpo = corpo
  .replace(/&#(\d+);/g, (m, d) => { try { return String.fromCharCode(parseInt(d, 10)); } catch (e) { return m; } })
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/\s+\n/g, '\n').trim();
corpo = corpo.substring(0, 8000);
const msgId = String((j.metadata && j.metadata['message-id']) || j.messageId || '').substring(0, 300) || null;

// so avisa emails que chegaram de ontem pra ca (evita enxurrada de nao-lidos antigos na ativacao)
let notificar = true;
try {
  const dt = j.date ? new Date(j.date) : null;
  if (dt && !isNaN(dt) && (Date.now() - dt.getTime()) > 36 * 3600 * 1000) notificar = false;
} catch (e) {}

const trecho = corpo.substring(0, 350) + (corpo.length > 350 ? '…' : '');
const texto = '📧 Email novo em contato@thiagonicezio.com\n\nDe: ' + (de.nome ? de.nome + ' <' + de.email + '>' : de.email) +
  '\nAssunto: ' + assunto + '\n\n' + (trecho || '(sem texto)') +
  '\n\nQuer que eu responda? Me fala o que dizer que eu monto e te mostro antes.';

const sql = "INSERT INTO giulia_emails (de, de_nome, assunto, corpo, message_id) VALUES ('" +
  esc(de.email) + "', '" + esc(de.nome) + "', '" + esc(assunto) + "', '" + esc(corpo) + "', " +
  (msgId ? "'" + esc(msgId) + "'" : 'NULL') + ")" +
  (msgId ? " ON CONFLICT (message_id) WHERE message_id IS NOT NULL DO NOTHING" : '') +
  " RETURNING id;";

return [{ json: { sql, notificar, texto } }];

// Depois do aviso no WhatsApp: registra na memoria e marca notificado.
const prep = $('Preparar Email Recebido').first().json;
const salvo = $('Salvar Email').first().json || {};
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
let sql = "INSERT INTO giulia_memoria (role, content, from_numero) VALUES ('assistant', '" + esc(prep.texto) + "', '5511910441709');";
if (salvo.id) sql += "\nUPDATE giulia_emails SET notificado = true WHERE id = " + parseInt(salvo.id, 10) + ";";
return [{ json: { sql } }];

// Gate + normalizacao do pedido de envio (so o Thiago).
const b = items[0].json.body || items[0].json || {};
const dono = String(b.dono || '').replace(/[^0-9]/g, '');
if (dono !== '5511910441709') return [];
return [{ json: { dono, pendente_id: b.pendente_id ? parseInt(b.pendente_id, 10) : null } }];

// Escolhe o pendente confirmado e prepara o envio.
const ped = $('Preparar Envio Email').first().json;
const pendentes = $('Carregar Pendente Email').all().map(i => i.json).filter(p => p && p.id);
let pend = ped.pendente_id ? pendentes.find(p => String(p.id) === String(ped.pendente_id)) : pendentes[0];
if (!pend) {
  return [{ json: { ok: false, dono: ped.dono, texto: 'Nao achei email aguardando confirmacao. Me pede de novo que eu monto na hora.' } }];
}
const escHtml = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const corpoHtml = escHtml(pend.corpo).replace(/[\u0080-\uFFFF]/g, ch => '&#' + ch.charCodeAt(0) + ';').replace(/\n/g, '<br>');
const html = '<div style="font-family: Arial, Helvetica, sans-serif; font-size: 14px; color: #222; line-height: 1.55; max-width: 640px;">' +
  corpoHtml +
  '<br><br><table style="border-left: 3px solid #1a73b5; padding-left: 12px;" cellpadding="0" cellspacing="0"><tr><td style="padding-left: 12px; font-family: Arial, sans-serif; font-size: 13px; color: #333;">' +
  '<strong style="font-size: 15px; color: #111;">Thiago Nicezio</strong><br>' +
  '<span style="color: #555;">+55 11 91044-1709 &nbsp;|&nbsp; contato@thiagonicezio.com</span>' +
  '</td></tr></table></div>';
return [{ json: { ok: true, dono: ped.dono, pend_id: pend.id, destinatario: pend.destinatario, assunto: pend.assunto, corpo: pend.corpo, html } }];

// Marca enviado + memoria + texto de confirmacao pro Thiago.
const m = $('Montar Envio').first().json;
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
const texto = '📤 Email enviado ✅\nPara: ' + m.destinatario + '\nAssunto: ' + m.assunto;
const sql = "UPDATE giulia_email_pendentes SET status = 'enviado', resolvido_em = NOW() WHERE id = " + parseInt(m.pend_id, 10) + ";\n" +
  "INSERT INTO giulia_memoria (role, content, from_numero) VALUES ('assistant', '" + esc(texto) + "', '5511910441709');";
return [{ json: { sql, texto, dono: '5511910441709' } }];
